import { useCallback, useEffect, useRef, useState } from "react";

/**
 * Formats a number of seconds as H:MM:SS or M:SS.
 */
function formatTime(totalSeconds) {
  const safe = Math.max(0, Math.floor(totalSeconds));
  const hours = Math.floor(safe / 3600);
  const minutes = Math.floor((safe % 3600) / 60);
  const seconds = safe % 60;

  const pad = (n) => String(n).padStart(2, "0");

  return hours > 0
    ? `${hours}:${pad(minutes)}:${pad(seconds)}`
    : `${minutes}:${pad(seconds)}`;
}

/**
 * CountdownTimer
 *
 * @param {number}   seconds     Starting number of seconds to count down from.
 * @param {boolean}  autoStart   Begin counting immediately on mount. Default true.
 * @param {function} onComplete  Called once when the timer reaches zero.
 * @param {boolean}  showControls Render start/pause/reset buttons. Default true.
 */
export default function CountdownTimer({
  seconds,
  autoStart = true,
  onComplete,
  showControls = true,
}) {
  const [remaining, setRemaining] = useState(seconds);
  const [isRunning, setIsRunning] = useState(autoStart);

  // Keep the latest onComplete without restarting the interval each render.
  const onCompleteRef = useRef(onComplete);
  useEffect(() => {
    onCompleteRef.current = onComplete;
  }, [onComplete]);

  // Reset when the caller changes the starting duration.
  useEffect(() => {
    setRemaining(seconds);
    setIsRunning(autoStart);
  }, [seconds, autoStart]);

  useEffect(() => {
    if (!isRunning || remaining <= 0) return;

    // Anchor to wall-clock time so the countdown stays accurate even if
    // timers are throttled (background tabs) or the event loop is busy.
    const endsAt = Date.now() + remaining * 1000;

    const id = setInterval(() => {
      const left = Math.ceil((endsAt - Date.now()) / 1000);

      if (left <= 0) {
        setRemaining(0);
        setIsRunning(false);
        onCompleteRef.current?.();
      } else {
        setRemaining(left);
      }
    }, 250);

    return () => clearInterval(id);
    // `remaining` is intentionally omitted: it would re-anchor every tick.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isRunning]);

  const start = useCallback(() => {
    if (remaining > 0) setIsRunning(true);
  }, [remaining]);

  const pause = useCallback(() => setIsRunning(false), []);

  const reset = useCallback(() => {
    setIsRunning(false);
    setRemaining(seconds);
  }, [seconds]);

  const isDone = remaining <= 0;

  return (
    <div className="countdown-timer">
      <time
        role="timer"
        aria-live={isDone ? "assertive" : "off"}
        dateTime={`PT${Math.max(0, remaining)}S`}
        className="countdown-timer__display"
      >
        {formatTime(remaining)}
      </time>

      {showControls && (
        <div className="countdown-timer__controls">
          <button type="button" onClick={isRunning ? pause : start} disabled={isDone}>
            {isRunning ? "Pause" : "Start"}
          </button>
          <button type="button" onClick={reset} disabled={remaining === seconds && !isRunning}>
            Reset
          </button>
        </div>
      )}
    </div>
  );
}
```

